+import React, { useEffect } from "react";
+
+import { ChevronFace, ContextMenuButton, useContextMenu } from "../../structures/ContextMenu";
+import UIStore from "../../../stores/UIStore";
+import IconizedContextMenu, { IconizedContextMenuOptionList } from "./IconizedContextMenu";
+
+interface Props extends Omit<React.ComponentProps<typeof ContextMenuButton>, "onClick" | "isExpanded" | "label"> {
+    options: React.ReactNode[];
+    title: string;
+}
+
+export const KebabContextMenu: React.FC<Props> = ({ options, title, disabled, ...props }) => {
+    const [isOpen, button, open, close] = useContextMenu();
+
+    useEffect(() => {
+        if (disabled && isOpen) close();
+    }, [disabled, isOpen, close]);
+
+    return <>
+        <ContextMenuButton
+            {...props}
+            inputRef={button}
+            label={title}
+            isExpanded={isOpen}
+            disabled={disabled}
+            aria-disabled={disabled}
+            onClick={(ev) => {
+                button.current?.focus();
+                open(ev);
+            }}
+            className={`mx_KebabContextMenu_trigger ${props.className || ""}`}
+        >
+            <span className="mx_KebabContextMenu_icon" aria-hidden="true" />
+        </ContextMenuButton>
+        { isOpen && button.current && <IconizedContextMenu
+            onFinished={close}
+            rightAligned
+            chevronFace={ChevronFace.None}
+            top={button.current.getBoundingClientRect().bottom}
+            right={UIStore.instance.windowWidth - button.current.getBoundingClientRect().right}
+        >
+            <IconizedContextMenuOptionList red>{ options }</IconizedContextMenuOptionList>
+        </IconizedContextMenu> }
+    </>;
+};
